// MemberStatement ONE record, two projections. The member and an officer of the member's
// society are served by the same handler and the same query; the
// projection decides only whether attribution (postedBy) is included.
// Every figure is identical in both.
type MemberStatement struct {
	// ChargedInPeriod What the member was charged in the period, NET OF REFUNDS, from the
	// member's side (positive = charged), each component apart (D-03). A
	// charge refunded by a reversal nets to zero; it is never counted twice.
	ChargedInPeriod ChargedInPeriod `json:"chargedInPeriod"`

	// ClosingSavingsBalanceKobo A BALANCE, FROM THE MEMBER'S SIDE — NOT a §0 line. Positive means the
	// society owes the member this much (they are in credit). Lines follow §0
	// (positive = debit), so the member's savings lines that build this
	// balance are negative; this field is their negation, computed once, here,
	// so no client ever negates anything. Decided 2026-10-01.
	ClosingSavingsBalanceKobo SavingsBalance      `json:"closingSavingsBalanceKobo"`
	From                      *openapi_types.Date `json:"from"`
	MemberId                  openapi_types.UUID  `json:"memberId"`
	MemberName                string              `json:"memberName"`
	MemberNumber              string              `json:"memberNumber"`

	// OpeningSavingsBalanceKobo A BALANCE, FROM THE MEMBER'S SIDE — NOT a §0 line. Positive means the
	// society owes the member this much (they are in credit). Lines follow §0
	// (positive = debit), so the member's savings lines that build this
	// balance are negative; this field is their negation, computed once, here,
	// so no client ever negates anything. Decided 2026-10-01.
	OpeningSavingsBalanceKobo SavingsBalance `json:"openingSavingsBalanceKobo"`

	// Projection Which projection this is, so a client never infers it from a missing field.
	Projection MemberStatementProjection `json:"projection"`

	// Rows Ordered by value date (NULL first), then postedAt, then entryId: the
	// books' order (decided 2026-10-05). Deterministic (§5).
	Rows      []StatementRow      `json:"rows"`
	SocietyId openapi_types.UUID  `json:"societyId"`
	To        *openapi_types.Date `json:"to"`
}

