// ServerInterface represents all server handlers.
type ServerInterface interface {
	// One approval request, in the caller's projection
	// (GET /approvals/{requestId})
	GetApproval(w http.ResponseWriter, r *http.Request, requestId openapi_types.UUID)
	// Authorise an approved withdrawal to execute (the hold), on the authoriser's own PIN step-up
	// (POST /approvals/{requestId}/holds)
	AuthorisePayout(w http.ResponseWriter, r *http.Request, requestId openapi_types.UUID)
	// Reject a request with one of the four reasons, resting on the rejecter's own PIN step-up
	// (POST /approvals/{requestId}/rejections)
	RejectApproval(w http.ResponseWriter, r *http.Request, requestId openapi_types.UUID)
	// Sign a request, resting on the signer's own PIN step-up
	// (POST /approvals/{requestId}/signatures)
	SignApproval(w http.ResponseWriter, r *http.Request, requestId openapi_types.UUID)
	// Complete a new-device sign-in with the code sent to the registered phone (public)
	// (POST /auth/codes/verify)
	PostVerifyCode(w http.ResponseWriter, r *http.Request)
	// Trust a first device with an enrolment code, and sign in on it (public)
	// (POST /auth/enrol)
	PostEnrol(w http.ResponseWriter, r *http.Request)
	// The PIN step-up — a proof that authorises ONE act of ONE kind (0005)
	// (POST /auth/pin-proofs)
	PostPinProof(w http.ResponseWriter, r *http.Request)
	// Sign in with the one credential box and a PIN (public)
	// (POST /auth/sign-in)
	PostSignIn(w http.ResponseWriter, r *http.Request)
	// End this session
	// (POST /auth/sign-out)
	PostSignOut(w http.ResponseWriter, r *http.Request)
	// Liveness and database reachability
	// (GET /healthz)
	GetHealthz(w http.ResponseWriter, r *http.Request)
	// Release a hold whose transfer definitively failed, saying why
	// (POST /holds/{holdId}/releases)
	ReleaseHold(w http.ResponseWriter, r *http.Request, holdId openapi_types.UUID)
	// One loan's position as at a value date
	// (GET /loans/{loanId})
	GetLoan(w http.ResponseWriter, r *http.Request, loanId openapi_types.UUID, params GetLoanParams)
	// Who the caller is - their own member records and current posts
	// (GET /me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// A member's bank details and every change to them, for the member and their society's officers
	// (GET /members/{memberId}/bank-account)
	GetBankAccount(w http.ResponseWriter, r *http.Request, memberId openapi_types.UUID)
	// The member sets their own bank details, on their own PIN; VFD's name check follows
	// (PUT /members/{memberId}/bank-account)
	SetOwnBankAccount(w http.ResponseWriter, r *http.Request, memberId openapi_types.UUID)
	// Where the member pays a contribution — their society's own VFD account
	// (GET /members/{memberId}/contribution-account)
	GetContributionAccount(w http.ResponseWriter, r *http.Request, memberId openapi_types.UUID)
	// A member's own claims, newest first, each in its current state
	// (GET /members/{memberId}/contribution-claims)
	GetContributionClaims(w http.ResponseWriter, r *http.Request, memberId openapi_types.UUID, params GetContributionClaimsParams)
	// Claim a payment into the society's VFD account as the member's contribution
	// (POST /members/{memberId}/contribution-claims)
	ClaimContribution(w http.ResponseWriter, r *http.Request, memberId openapi_types.UUID)
	// A member's loans as at a value date (the member, or an officer of their society)
	// (GET /members/{memberId}/loans)
	GetMemberLoans(w http.ResponseWriter, r *http.Request, memberId openapi_types.UUID, params GetMemberLoansParams)
	// A member's savings statement — one record, two projections
	// (GET /members/{memberId}/statement)
	GetMemberStatement(w http.ResponseWriter, r *http.Request, memberId openapi_types.UUID, params GetMemberStatementParams)
	// A member's savings, what they may withdraw now, and what was deducted and why
	// (GET /members/{memberId}/withdrawable)
	GetMemberWithdrawable(w http.ResponseWriter, r *http.Request, memberId openapi_types.UUID)
	// What a withdrawal of an amount would cost today (indicative)
	// (GET /members/{memberId}/withdrawal-quote)
	GetWithdrawalQuote(w http.ResponseWriter, r *http.Request, memberId openapi_types.UUID, params GetWithdrawalQuoteParams)
	// A member's own withdrawal requests, newest first, in the member projection
	// (GET /members/{memberId}/withdrawal-requests)
	GetMemberWithdrawalRequests(w http.ResponseWriter, r *http.Request, memberId openapi_types.UUID, params GetMemberWithdrawalRequestsParams)
	// Confirm a proposal, as a second officer, on your own PIN step-up; it takes effect in the same transaction
	// (POST /payment-resolutions/{resolutionId}/confirmations)
	ConfirmPaymentResolution(w http.ResponseWriter, r *http.Request, resolutionId openapi_types.UUID)
	// Reject a proposal, with a reason, on your own PIN step-up (the proposer may withdraw their own); nothing happens
	// (POST /payment-resolutions/{resolutionId}/rejections)
	RejectPaymentResolution(w http.ResponseWriter, r *http.Request, resolutionId openapi_types.UUID)
	// The society's chart of accounts
	// (GET /societies/{societyId}/accounts)
	GetChartOfAccounts(w http.ResponseWriter, r *http.Request, societyId openapi_types.UUID)
	// One account's entries with a running balance
	// (GET /societies/{societyId}/accounts/{accountCode}/ledger)
	GetGeneralLedger(w http.ResponseWriter, r *http.Request, societyId openapi_types.UUID, accountCode string, params GetGeneralLedgerParams)
	// The society's approval requests, newest first, in the officer projection
	// (GET /societies/{societyId}/approval-requests)
	GetSocietyApprovalRequests(w http.ResponseWriter, r *http.Request, societyId openapi_types.UUID, params GetSocietyApprovalRequestsParams)
	// The society's branches, so an import's preview catches an unknown branch before any PIN
	// (GET /societies/{societyId}/branches)
	ListBranches(w http.ResponseWriter, r *http.Request, societyId openapi_types.UUID)
	// Record a contribution that arrived, on the recorder's own PIN step-up
	// (POST /societies/{societyId}/contributions)
	RecordContribution(w http.ResponseWriter, r *http.Request, societyId openapi_types.UUID, params RecordContributionParams)
	// Entries with every line, filtered by reference, member, actor and value date
	// (GET /societies/{societyId}/journal)
	GetJournal(w http.ResponseWriter, r *http.Request, societyId openapi_types.UUID, params GetJournalParams)
	// postAll — commit a whole import in ONE transaction (LEDGER_CONTRACT §1)
	// (POST /societies/{societyId}/ledger/batches)
	PostLedgerBatch(w http.ResponseWriter, r *http.Request, societyId openapi_types.UUID, params PostLedgerBatchParams)
	// The society's loan book as at a value date (officers only)
	// (GET /societies/{societyId}/loans)
	GetSocietyLoans(w http.ResponseWriter, r *http.Request, societyId openapi_types.UUID, params GetSocietyLoansParams)
	// Find a society's members, for an officer (the register; the issuing screen)
	// (GET /societies/{societyId}/members)
	FindMembers(w http.ResponseWriter, r *http.Request, societyId openapi_types.UUID, params FindMembersParams)
	// The secretary adds one member (whoever joins next month)
	// (POST /societies/{societyId}/members)
	RegisterMember(w http.ResponseWriter, r *http.Request, societyId openapi_types.UUID)
	// The register import — a society's members, in ONE transaction
	// (POST /societies/{societyId}/members/batches)
	RegisterMembers(w http.ResponseWriter, r *http.Request, societyId openapi_types.UUID, params RegisterMembersParams)
	// An officer sets the bank details of a member who cannot sign in, on the officer's own PIN
	// (PUT /societies/{societyId}/members/{memberId}/bank-account)
	SetMemberBankAccount(w http.ResponseWriter, r *http.Request, societyId openapi_types.UUID, memberId openapi_types.UUID)
	// A signatory confirms a bank's name for a member that does not match the register, after looking
	// (POST /societies/{societyId}/members/{memberId}/bank-account/confirmation)
	ConfirmBankName(w http.ResponseWriter, r *http.Request, societyId openapi_types.UUID, memberId openapi_types.UUID)
	// The secretary sets (or clears) a member's email, on their own PIN step-up
	// (PUT /societies/{societyId}/members/{memberId}/email)
	SetMemberEmail(w http.ResponseWriter, r *http.Request, societyId openapi_types.UUID, memberId openapi_types.UUID)
	// A member's enrolment codes, for an officer of the society — who issued each, when, and the device it trusted
	// (GET /societies/{societyId}/members/{memberId}/enrolment-codes)
	GetEnrolmentCodes(w http.ResponseWriter, r *http.Request, societyId openapi_types.UUID, memberId openapi_types.UUID)
	// An officer issues a member's enrolment code, on their own step-up; a signatory's comes in two halves
	// (POST /societies/{societyId}/members/{memberId}/enrolment-codes)
	IssueEnrolmentCode(w http.ResponseWriter, r *http.Request, societyId openapi_types.UUID, memberId openapi_types.UUID)
	// An officer releases a member who is locked out of signing in, in person, saying why
	// (POST /societies/{societyId}/members/{memberId}/lock-releases)
	ReleaseLock(w http.ResponseWriter, r *http.Request, societyId openapi_types.UUID, memberId openapi_types.UUID)
	// A member's status changes, newest first, for the society's officers
	// (GET /societies/{societyId}/members/{memberId}/status-changes)
	GetMemberStatusChanges(w http.ResponseWriter, r *http.Request, societyId openapi_types.UUID, memberId openapi_types.UUID)
	// The secretary suspends, reinstates, or records the departure of a member, on their own PIN, with a reason
	// (POST /societies/{societyId}/members/{memberId}/status-changes)
	ChangeMemberStatus(w http.ResponseWriter, r *http.Request, societyId openapi_types.UUID, memberId openapi_types.UUID)
	// The society's payment resolutions, newest first
	// (GET /societies/{societyId}/payment-resolutions)
	GetPaymentResolutions(w http.ResponseWriter, r *http.Request, societyId openapi_types.UUID, params GetPaymentResolutionsParams)
	// Propose a payment's resolution, on the proposer's own PIN step-up; a second officer confirms it
	// (POST /societies/{societyId}/payment-resolutions)
	ProposePaymentResolution(w http.ResponseWriter, r *http.Request, societyId openapi_types.UUID, params ProposePaymentResolutionParams)
	// Record a payout that happened, on the recorder's own PIN step-up
	// (POST /societies/{societyId}/payouts)
	RecordPayout(w http.ResponseWriter, r *http.Request, societyId openapi_types.UUID)
	// Every account's debits, credits and balance as at a date
	// (GET /societies/{societyId}/trial-balance)
	GetTrialBalance(w http.ResponseWriter, r *http.Request, societyId openapi_types.UUID, params GetTrialBalanceParams)
	// Payments VFD confirmed into the society's account that are not credited, oldest first, each with every claim on its session
	// (GET /societies/{societyId}/unmatched-payments)
	GetUnmatchedPayments(w http.ResponseWriter, r *http.Request, societyId openapi_types.UUID, params GetUnmatchedPaymentsParams)
	// What a person must act on in the society's money at VFD, oldest first
	// (GET /societies/{societyId}/wallet-exceptions)
	GetWalletExceptions(w http.ResponseWriter, r *http.Request, societyId openapi_types.UUID)
	// Raise a withdrawal request, on the raiser's own PIN step-up
	// (POST /societies/{societyId}/withdrawal-requests)
	RaiseWithdrawalRequest(w http.ResponseWriter, r *http.Request, societyId openapi_types.UUID, params RaiseWithdrawalRequestParams)
	// VFD's notification of money arriving, kept as received, never believed
	// (POST /webhooks/vfd)
	ReceiveVfdNotification(w http.ResponseWriter, r *http.Request, params ReceiveVfdNotificationParams)
}

